<?php require_once __DIR__ . "/remember.php"; $error=$_GET["error"]??""; $loggedout=isset($_GET["loggedout"]); ?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Login - StudentHub</title><link rel="stylesheet" href="style.css"></head><body><header><h1>StudentHub Portal</h1><p>Secure Login</p></header><nav><a href="index.php">Home</a><a href="about.php">About</a><a href="login.php">Login</a></nav><main class="login-card"><h2>Login to Your Account</h2><?php if($error==="invalid"){?><p class="error">Invalid username or password.</p><?php }elseif($error==="inactive"){?><p class="error">Your account is inactive.</p><?php }elseif($error==="timeout"){?><p class="error">Session expired. Please login again.</p><?php }if($loggedout){?><p class="success">You have logged out successfully.</p><?php }?><form action="login_process.php" method="POST"><label for="username">Username or Email</label><input type="text" id="username" name="username" autocomplete="username" required><label for="password">Password</label><input type="password" id="password" name="password" autocomplete="current-password" required><p class="remember"><input type="checkbox" id="remember" name="remember" value="1"><label for="remember">Remember Me (30 days)</label></p><button type="submit">Login</button></form></main><footer>© 2026 StudentHub Portal - CHARUSAT</footer></body></html>